// Cyclic Noise (Ray Marching)
// Ispirata a "Cyclic noise 2D" di nimitz (@stormoid) - https://www.shadertoy.com/view/fcjXzh (MIT)
// Porta il cuore della cyclic noise in 3D e la usa per COLORARE la superficie
// ray-marciata: assegna textureCol partendo dal punto di hit pModel.
//
// Variabili dell'engine disponibili in questo blocco (tab Ray Marching):
//   pModel       = punto di hit sulla superficie (vec3, model space)
//   n_model      = normale alla superficie nel punto di hit (vec3)
//   textureCol   = colore da assegnare (gia' inizializzato a ubuf.color)
//   ubuf.u_time  = tempo animato; ubuf.u_col1 / ubuf.u_col2 = colori del dock
// NB: niente mainImage, niente return, niente gl_FragCoord in questo tab.

// --- Cyclic noise 3D: loop iterato di |dot(cos,sin)| con distorsione e rotazione ---
float result = 0.0;
float z = 0.95;
float distort = 2.1;
float dstAmount = 0.10;
float wsum = 0.0;

// matrice di rotazione (l'originale 2D usava una mat2 ~13deg *1.5)
mat3 m2 = mat3(
    0.97367,  0.22798, 0.0,
   -0.22798,  0.97367, 0.0,
    0.0,      0.0,     1.0) * 1.5;

// coordinate: il punto sulla superficie + leggero scorrimento temporale
vec3 p = pModel * 2.3 + vec3(0.0, 0.0, ubuf.u_time * 0.05);

for (int i = 0; i < 8; i++) {
    p += sin(p.yzx * distort + ubuf.u_time * 0.27 * pow(distort, 1.35)) * dstAmount;
    result += abs(dot(cos(p), sin(p.zxy)) * z);
    wsum   += z;
    z       *= 0.65;
    distort *= 1.35;
    p        = m2 * p;
}
float ncyc = result / wsum;   // ~[0,1]

// bande cromatiche come nell'originale (sin di tre frequenze sfasate)
vec3 flow = sin(vec3(1.15, 1.65, 2.25) * ncyc * 6.2 + 4.2) * 0.5 + 0.5;

// mescola i due colori del dock seguendo il flusso del rumore
vec3 cyclicCol = mix(ubuf.u_col2, ubuf.u_col1, flow);

// sheen di bordo (fresnel) dalla normale: accende le creste del flusso
float fres = pow(1.0 - abs(n_model.z), 2.0);
cyclicCol += ubuf.u_col1 * fres * 0.25 * ncyc;

textureCol = cyclicCol;
